class Du(BtsComponent):
    """ Represents generic Distributed Unit. """

    _MISSING_ALARM_ATTRS_ERROR_MSG = 'No alarm attributes were provided for alarm on {} but at least one must be used'

    def __init__(self,
                 parent: BtsComponent,
                 du_info: ApiResponse,
                 api: DuApi,
                 api_alias: str,
                 du_init_config: DuConfig,
                 du_alarms_watchdog: Union[None, alarms_watchdog] = None):
        """
        :param parent: BTS component to which this DU is connected; usually it is CU
        :param du_info: information about this DU received as a response to API request
                        must contain following data:
                        {'dist_names': {'config': 'MRBTS-1/NRBTS-1/NRDU-1'},
                         'id': '1',
                         'name': 'NRDU-1'}
        :param api: API used for performing operations on this DU
        :param api_alias: name of opened API connection which this DU should use
        :param du_init_config: configuration details, taken from init file, of this DU
        :param du_alarms_watchdog: alarms watchdog instance used for watching alarms on this DU;
                                   defaults to None (new instance will be created)
        """
        log_info('Creating new DU')
        super(Du, self).__init__(du_info['name'])
        self._parent = parent
        self._id = du_info['id']
        self._config_dist_name = du_info['dist_names']['config']
        self._config = ConfigDu(mrbts_id=self._config_dist_name.split('/')[0].split('-')[1],
                                nrbts_id=self._config_dist_name.split('/')[1].split('-')[1],
                                api=api,
                                api_alias=api_alias)
        self._sw = SwDu(api=api, api_alias=api_alias)
        self._api = api
        self._api_alias = api_alias
        self._webem_alias = f'{api_alias}_webem'
        self._webem = WebemDu(sw_stream=str(self._sw.version.stream),
                              selenium_alias=self._webem_alias)
        self._ssh = ssh()
        self._ssh_alias = self._name
        self._du_init_config = du_init_config
        self._instance_id = self._du_init_config.instance_id
        self._alarms_watchdog = du_alarms_watchdog if du_alarms_watchdog else alarms_watchdog()
        self._rmods = ComponentCollection()
        self._pods = []
        self._test_model = TestModel(api=api, api_alias=api_alias)
        self._rf_scan = RfScan(api=api, api_alias=api_alias)
        self._rf_diagnostic_test = RfDiagnosticTest(api=api, api_alias=api_alias)
        self._antenna_line_online_monitoring = AntennaLineOnlineMonitoring(webem=self._webem, api=api,
                                                                           api_alias=api_alias)
        log_debug(f'DU details:\n'
                  f'name={self._name}\n'
                  f'id={self._id}\n'
                  f'config_dist_name={self._config_dist_name}\n'
                  f'instance_id={self._instance_id}\n'
                  f'parent={self._parent.name}')

    def __eq__(self, other):
        return self._name == other.name

    @property
    def string_representation(self):
        info = f'    {self._name} (SW: {self._sw.version.name}):'

        for rmod in self._rmods:
            info += f'\n{rmod.string_representation}'

        return info

    @property
    def init_config(self) -> DuConfig:
        """ Returns configuration details, taken from init file, of this DU. """
        return self._du_init_config

    @property
    def cu(self) -> BtsComponent:
        """ Returns CU to which this DU is connected. """
        return self._parent

    @property
    def config(self) -> ConfigDu:
        """ Returns configuration (parameters and their values) of this DU. """
        return self._config

    @property
    def sw(self) -> SwDu:
        """ Returns software manager for this DU. """
        return self._sw

    @property
    def alarms_watchdog(self) -> alarms_watchdog:
        """ Returns Alarms Watchdog used for watching alarms on this DU. """
        return self._alarms_watchdog

    @property
    def rmods(self) -> ComponentCollection:
        """ Returns all RMODs connected to this DU. """
        return self._rmods

    @property
    def cells(self) -> ComponentCollection:
        """ Returns all Cells configured on this DU. """
        cells = ComponentCollection()
        [cells.extend(rmod.cells) for rmod in self.rmods]

        unique_cells = ComponentCollection()
        [unique_cells.append(cell) for cell in cells if cell not in unique_cells]

        return unique_cells

    @property
    def ssh_details(self) -> SshConfig:
        """ Returns SSH connection details for this DU. """
        return self._du_init_config.cloud_deployment.cloud_hosting.master_node.ssh_connection_details

    @property
    def instance_id(self) -> int:
        """ Returns instance id for this DU; i.e. 8363"""
        return self._instance_id

    @property
    def test_model(self) -> TestModel:
        """ Returns Test Model which allows to run Test Models on this DU."""
        return self._test_model

    @property
    def rf_scan(self) -> RfScan:
        """ Returns RF Scan which allows to run RF Scans on this DU."""
        return self._rf_scan

    @property
    def rf_diagnostic_test(self) -> RfDiagnosticTest:
        """ Returns RF Diagnostic Test which allows to run RF Diagnostic Tests on this DU."""
        return self._rf_diagnostic_test

    @property
    def antenna_line_online_monitoring(self) -> AntennaLineOnlineMonitoring:
        """ Returns Antenna Line Online Monitoring which allows to run Antenna Line Online Monitoring on this DU."""
        return self._antenna_line_online_monitoring

    @property
    def webem(self) -> WebemDu:
        """ Returns WebEM interface which allows to interact with WebEM of this DU."""
        if not self._webem.is_logged_in:
            raise UsageError(f'WebEM interface for {self._name} was not initialized, please call start_webem() first')
        return self._webem

    @pretty_log
    def start_webem(self, download_dir_path: str, browser: str = 'Chrome'):
        """
        Initializes WebEM interface for this DU. Sets download directory, enables virtual display and logs in.
        Please remember to call close_webem() after finishing operations on WebEM to properly perform closing WebEM.

        :param download_dir_path: absolute path to directory where files downloaded by browser will be saved; e.g.:
                                  '/home/ute/Desktop/result/downloads'
        :param browser: browser to be used, supported browsers: 'Chrome', 'Firefox'; defaults to 'Chrome'
        :return: initialized WebEM interface for this DU
        """
        if not self._webem.is_logged_in:
            du_http = self._du_init_config.oam_http_connection_details
            self._webem.set_download_dir_path(download_dir_path=download_dir_path)
            self._webem.set_debug_dir_path(debug_dir_path=f'{download_dir_path}/selenium_debug')
            self._webem.enable_virtual_display()

            log_info('Opening DU WebEM', to_console=True)
            self._webem.login(url=f'https://{du_http.addr}',
                              username=du_http.username,
                              password=du_http.password,
                              browser=browser,
                              is_headless=True)

    @pretty_log
    def close_webem(self):
        """
        Closes WebEM. Logs out from WebEM, disables virtual display and removes WebEM interface.
        """
        if self._webem.is_logged_in:
            log_info('Closing DU WebEM', to_console=True)
            self._webem.logout()
            self._webem.disable_virtual_display()
        else:
            log_debug('WebEM interface was not initialized, WebEM closing skipped')

    @pretty_log
    def load(self):
        """
        Loads info about this DU and all components currently connected to it.
        Each time current DU configuration changes (i.e. due to SW update or recomissioning which adds/removes BTS component)
        DU needs to be reloaded using this method.
        """
        log_info(f'Loading {self._name}', to_console=True)
        self._sw.load()
        self._rmods.clear()
        rmods_info = self._api.get_rmods_status(vdu_connection=self._api_alias)
        rmods_ssh_ips = self._get_rmods_ssh_ips(rmods_info)
        rmods_fhgw_init_configs = {rmod_init_config.serial_number: rmod_init_config
                                   for rmod_init_config in self._du_init_config.fhgws[0].rus} if self._du_init_config.fhgws else {}
        rmods_dc_init_configs = {rmod_init_config.serial_number: rmod_init_config
                                 for rmod_init_config in self._du_init_config.rus} if self._du_init_config.rus else {}
        for rmod_info in rmods_info:
            rmod_serial_number = rmod_info.get('serial_number')

            if rmod_serial_number:
                rmod_ssh_ip = rmods_ssh_ips[rmod_serial_number]
                rmod_init_config = None
                is_rmod_dc = None

                if rmod_serial_number in rmods_fhgw_init_configs:
                    rmod_init_config = rmods_fhgw_init_configs[rmod_serial_number]
                    is_rmod_dc = False
                elif rmod_serial_number in rmods_dc_init_configs:
                    rmod_init_config = rmods_dc_init_configs[rmod_serial_number]
                    is_rmod_dc = True

                if rmod_init_config:
                    rmod = CloudRmod(parent=self,
                                     rmod_info=rmod_info,
                                     api=self._api,
                                     api_alias=self._api_alias,
                                     ssh_ip=rmod_ssh_ip,
                                     rmod_init_config=rmod_init_config,
                                     is_dc=is_rmod_dc)
                    rmod.load()
                    self._rmods.append(rmod)

        self._pods = self._get_pods_names()

    @pretty_log
    def check_if_reachable(self, delay: int = 0, timeout: int = 5):
        """
        Checks whether this DU is reachable via HTTPS.
        :param delay: time (in seconds) to wait before checking if DU is reachable;
                      defaults to 0 (no delay)
        :param timeout: time (in seconds) for DU to become reachable;
                        defaults to 5
        :raises ResultError: if DU doesn't become reachable before the timeout
        """
        self._check_if_reachable(delay, timeout)

    @pretty_log
    def check_if_unreachable(self, delay: int = 0, timeout: int = 5):
        """
        Checks whether this DU is unreachable via HTTPS.
        :param delay: time (in seconds) to wait before checking if DU is unreachable;
                      defaults to 0 (no delay)
        :param timeout: time (in seconds) for DU to become unreachable;
                        defaults to 5
        :raises ResultError: if DU doesn't become unreachable before the timeout
        """
        self._check_if_unreachable(delay, timeout)

    @pretty_log
    def reset(self, timeout: int = 0):
        """
        Resets this DU by sending appropriate API command.
        :param timeout: time (in seconds) in which operation should be successfully completed;
                        defaults to 0 (there will be no waiting for operation to complete)
        :raises TimeExceeded: if reset operation exceeds given timeout
        :raises ResultError: if reset operation fails
        """
        log_info(f'Resetting {self._name} with {timeout}s timeout', to_console=True)
        api_response = self._api.reset_vdu(timeout=5,
                                           vdu_connection=self._api_alias)

        if timeout:
            wait_for(expected_value='success',
                     abort_if='failure',
                     timeout=timeout,
                     callback=self._get_status_of_reset,
                     operation_id=api_response['id'])

    @pretty_log
    def reset_and_wait_for_on_air(self):
        """
        Resets this DU by sending appropriate API command and waits until it reaches On Air state.
        Maximum total time of sending API command, completing all intermediate checks and reaching On Air state will not exceed 845s.
        :raises UnexpectedState: if DU, at any point after performing reset, doesn't reach expected state (including final On Air state)
        :raises ResultError: if any other step fails
        """
        log_info(f'Resetting {self._name} and waiting until it reaches On Air state', to_console=True)
        self._api.reset_vdu(timeout=5, vdu_connection=self._api_alias)
        self._check_if_pods_are_restarting(timeout=60)
        self._check_if_unreachable(delay=0, timeout=60)
        self._check_if_reachable(delay=0, timeout=240)
        self._check_if_pods_are_running(timeout=180)
        self._check_state(state='on_air', timeout=360)

    @pretty_log
    def wait_for_reset(self):
        """
        Waits for DU reset to start and complete.
        Maximum total time of waiting for reset to start and complete will not exceed 540s.
        :raises UnexpectedState: if DU, at any point during reset, doesn't reach expected state
        :raises ResultError: if any other step fails
        """
        self._check_if_pods_are_restarting(timeout=60)
        self._check_if_unreachable(delay=0, timeout=60)
        self._check_if_reachable(delay=0, timeout=240)
        self._check_if_pods_are_running(timeout=180)

    @pretty_log
    def is_alarm_active(self, timeout: int = 0, **expected_attributes: str) -> bool:
        """
        Informs whether alarm with given attributes becomes active.
        :param timeout: time (in seconds) in which alarm should become active;
                        defaults to 0 (alarm should be active now)
        :param expected_attributes: keyword arguments representing alarm attributes and their expected values which
                                    should be used during active alarm verification;
                                    i.e. fault_id='49'
        :return: True if alarm with all provided attributes becomes active, False otherwise
        :raises UnsupportedAlarm: if no expected attributes are provided
        """
        return self._is_alarm_active(timeout, **expected_attributes)

    @pretty_log
    def check_active_alarm(self, timeout: int = 0, **expected_attributes: str):
        """
        Checks whether alarm with given attributes becomes active.
        :param timeout: time (in seconds) in which alarm should become active;
                        defaults to 0 (alarm should be active now)
        :param expected_attributes: keyword arguments representing alarm attributes and their expected values which
                                    should be used during active alarm verification;
                                    i.e. fault_id='49'
        :raises UnexpectedAlarm: if alarm with all provided attributes doesn't become active
        :raises UnsupportedAlarm: if no expected attributes are provided
        """
        alarm_is_active = self._is_alarm_active(timeout, **expected_attributes)

        if not alarm_is_active:
            raise UnexpectedAlarm(f'Expected alarm was not active on {self._name}')

    @pretty_log
    def is_alarm_inactive(self, timeout: int = 0, **expected_attributes: str) -> bool:
        """
        Informs whether alarm with given attributes becomes inactive.
        :param timeout: time (in seconds) in which alarm should become inactive;
                        defaults to 0 (alarm should be inactive now)
        :param expected_attributes: keyword arguments representing alarm attributes and their expected values which
                                    should be used during inactive alarm verification;
                                    i.e. fault_id='49'
        :return: True if alarm with all provided attributes becomes inactive, False otherwise
        :raises UnsupportedAlarm: if no expected attributes are provided
        """
        return self._is_alarm_inactive(timeout, **expected_attributes)

    @pretty_log
    def check_inactive_alarm(self, timeout: int = 0, **expected_attributes: str):
        """
        Checks whether alarm with given attributes becomes inactive.
        :param timeout: time (in seconds) in which alarm should become inactive;
                        defaults to 0 (alarm should be inactive now)
        :param expected_attributes: keyword arguments representing alarm attributes and their expected values which
                                    should be used during inactive alarm verification;
                                    i.e. fault_id='49'
        :raises UnexpectedAlarm: if alarm with all provided attributes doesn't become inactive
        :raises UnsupportedAlarm: if no expected attributes are provided
        """
        alarm_is_inactive = self._is_alarm_inactive(timeout, **expected_attributes)

        if not alarm_is_inactive:
            raise UnexpectedAlarm(f'Expected alarm is still active on {self._name}')

    @pretty_log
    def allow_alarm(self, **alarm_attributes: str):
        """
        Adds alarm with given attributes to list of allowed alarms on this DU.
        From now on such alarm will not be detected as disallowed if it becomes active.
        :param alarm_attributes: keyword arguments representing alarm attributes and their expected values which
                                 should be used during allowing alarm;
                                 i.e. fault_id='49'
        :raises UnsupportedAlarm: if no alarm attributes are provided
        """
        self._check_alarm_attributes(alarm_attributes)
        self._alarms_watchdog.allow_alarm(**alarm_attributes)

    @pretty_log
    def disallow_alarm(self, **alarm_attributes: str):
        """
        Removes alarm with given attributes from list of allowed alarms on this DU.
        From now on such alarm will be detected as disallowed if it becomes active.
        :param alarm_attributes: keyword arguments representing alarm attributes and their expected values which
                                 should be used during disallowing alarm;
                                 i.e. fault_id='49'
        :raises UnsupportedAlarm: if no alarm attributes are provided
        """
        self._check_alarm_attributes(alarm_attributes)
        self._alarms_watchdog.disallow_alarm(**alarm_attributes)

    @pretty_log
    def collect_snapshot(self, path: str) -> str:
        """
        Collects snapshot from this DU and stores it on local machine.
        :param path: absolute path to directory where snapshot should be stored; i.e. '/home/ute/logs'
        :return: absolute path to collected snapshot file, i.e. '/home/ute/logs/snapshot.zip'
        """
        log_info(f'Collecting snapshot from {self._name}', to_console=True)
        log_debug(f'Snapshot will bo stored in {path}')
        return self._api.get_local_snapshot(directory=path,
                                            compressed_or_not=True,
                                            vdu_connection=self._api_alias)

    @pretty_log
    def check_if_pods_are_running(self, timeout: int = 0, silent: bool = False):
        """
        Checks whether all PODs on this DU are running.
        :param timeout: time (in seconds) in which all PODs should begin running;
                        defaults to 0 (all PODs should be running now)
        :param silent: determines whether non-error logs should appear on console (False) or not (True);
                       defaults to False (non-error logs visible on console)
        :raises UnexpectedState: if at least one POD is not running
        """
        self._check_if_pods_are_running(timeout, silent)

    @pretty_log
    def check_if_pods_are_restarting(self, timeout: int = 0):
        """
        Checks whether all PODs on this DU are restarting.
        :param timeout: time (in seconds) in which all PODs should begin restarting;
                        defaults to 0 (all PODs should be restarting now)
        :raises UnexpectedState: if at least one POD is not restarting
        """
        self._check_if_pods_are_restarting(timeout)

    @pretty_log
    def download_file(self, file_path: str, local_dir_path: str) -> str:
        """
        Downloads file from this DU to local machine.
        :param file_path: absolute path to file on this DU which should be downloaded, i.e. '/tmp/snapshot.zip'
        :param local_dir_path: absolute path to directory on local machine where file should be downloaded, i.e. '/home/ute/Downloads'
        :return: absolute path to downloaded file on local machine, i.e. '/home/ute/Downloads/snapshot.zip'
        :raises ResultError: if any step of file downloading fails
        """
        log_info(f'Downloading file {file_path} from {self._name} to {local_dir_path} on local machine', to_console=True)
        du_ssh_config = self._du_init_config.cloud_deployment.cloud_hosting.master_node.ssh_connection_details
        error_msg = f'Downloading file {file_path} from {self._name} to {local_dir_path} failed due to unknown console output'

        try:
            command = f'scp {du_ssh_config.username}@{du_ssh_config.addr}:{file_path} {local_dir_path}'
            log_debug(f'Executing on {self._name}: {command}')
            console = spawn(command)
            output_id = console.expect(['Are you sure you want to continue connecting', 'password:'])

            if output_id == 0:
                command = 'yes'
                log_debug(f'Executing on {self._name}: {command}')
                console.sendline(command)
                output_id = console.expect([EOF, 'password:'])

            if output_id == 1:
                command = du_ssh_config.password
                log_debug(f'Executing on {self._name}: {command}')
                console.sendline(du_ssh_config.password)
                console.expect('100%')
                return f'{local_dir_path}/{file_path.split("/")[-1]}'
            else:
                raise ResultError(error_msg)

        except TIMEOUT:
            raise ResultError(error_msg)

    @pretty_log
    def remove_file(self, file_path: str):
        """
        Removes file from this DU. Won't fail if file does not exist.
        :param file_path: absolute path to file on this DU which should be removed, i.e. '/tmp/snapshot.zip'
        """
        log_info(f'Removing file {file_path} from {self._name}', to_console=True)
        try:
            self._connect_via_ssh()
            self._execute_via_ssh(f'rm -f {file_path}')
        finally:
            self._disconnect_via_ssh()

    def _get_expected_statuses(self, state: str) -> Dict[str, str]:
        expected_statuses = {'on_air': {'operational_state': 'onAir'},
                             'commissioned': {'operational_state': 'commissioned'},
                             'integrated_to_ran': {'operational_state': 'integrated to RAN'},
                             'test_dedicated_state': {'operational_state': 'test'}}

        if state not in expected_statuses:
            raise UnsupportedState(self._UNSUPPORTED_STATE_ERROR_MSG.format(state, self._name))

        return expected_statuses[state]

    def _get_current_statuses(self, statuses_names: List[str]) -> Dict[str, str]:
        current_statuses = {}
        du_info = self._api.get_vdu_state_data(vdu_connection=self._api_alias)

        for status_name in statuses_names:
            current_status_value = du_info.get(status_name)
            current_statuses[status_name] = current_status_value

        return current_statuses

    def _check_if_reachable(self, delay: int, timeout: int):
        timeout_msg = f" before {timeout}s timeout" if timeout else ""
        log_info(f'Checking if {self._name} is reachable{timeout_msg}', to_console=True)
        sleep(delay)
        check_if_ip_is_reachable_via_https(ip=self._du_init_config.oam_http_connection_details.addr, timeout=timeout)

    def _check_if_unreachable(self, delay: int, timeout: int):
        timeout_msg = f" before {timeout}s timeout" if timeout else ""
        log_info(f'Checking if {self._name} is unreachable{timeout_msg}', to_console=True)
        sleep(delay)
        check_if_ip_is_unreachable_via_https(ip=self._du_init_config.oam_http_connection_details.addr, timeout=timeout)

    def _get_status_of_reset(self, operation_id: str) -> str:
        api_response = self._api.get_reset_vdu_operation_status(operation_id=operation_id,
                                                                vdu_connection=self._api_alias)
        return api_response['status']

    def _is_alarm_active(self, timeout: int = 0, **expected_attributes: str) -> bool:
        self._check_alarm_attributes(expected_attributes)
        self._log_details_of_expected_active_alarm(timeout, expected_attributes)

        if timeout:
            try:
                return self._alarms_watchdog.wait_for_active_alarm(timeout=timeout, **expected_attributes)
            except AlarmInactive:
                return False
        else:
            return self._alarms_watchdog.is_alarm_active(**expected_attributes)

    def _is_alarm_inactive(self, timeout: int = 0, **expected_attributes: str) -> bool:
        self._check_alarm_attributes(expected_attributes)
        self._log_details_of_expected_inactive_alarm(timeout, expected_attributes)

        if timeout:
            try:
                return self._alarms_watchdog.wait_for_inactive_alarm(timeout=timeout, **expected_attributes)
            except AlarmActive:
                return False
        else:
            return not self._alarms_watchdog.is_alarm_active(**expected_attributes)

    def _check_alarm_attributes(self, expected_attributes):
        if not expected_attributes:
            raise UnsupportedAlarm(self._MISSING_ALARM_ATTRS_ERROR_MSG.format(self._name))

    def _log_details_of_expected_active_alarm(self, timeout: int, expected_attributes: Dict[str, str]):
        timeout_msg = f" before {timeout}s timeout" if timeout else ""
        log_info(f'Checking if expected alarm is active on {self._name}{timeout_msg}', to_console=True)
        log_debug(f'{self._name} expected active alarm: \n{expected_attributes}')

    def _log_details_of_expected_inactive_alarm(self, timeout: int, expected_attributes: Dict[str, str]):
        timeout_msg = f" before {timeout}s timeout" if timeout else ""
        log_info(f'Checking if expected alarm is inactive on {self._name}{timeout_msg}', to_console=True)
        log_debug(f'{self._name} expected inactive alarm: \n{expected_attributes}')

    def _connect_via_ssh(self):
        du_ssh = self._du_init_config.cloud_deployment.cloud_hosting.master_node.ssh_connection_details
        ssh_port = 22
        log_debug(f'Connecting to {self._name} via SSH using IP address {du_ssh.addr}:{ssh_port}')
        self._ssh.connect_to(hostname=du_ssh.addr,
                             username=du_ssh.username,
                             password=du_ssh.password,
                             port=ssh_port,
                             alias=self._ssh_alias)

    def _execute_via_ssh(self, cmd: str) -> str:
        log_debug(f'Executing on {self._name} via SSH: {cmd}')
        output = self._ssh.execute(command=cmd, connection=self._ssh_alias)
        log_debug(f'{self._name} SSH output: \n{output}')
        return output

    def _disconnect_via_ssh(self):
        log_debug(f'Disconnecting from {self._name} via SSH')
        self._ssh.disconnect(connection=self._ssh_alias)

    def _get_rmods_ssh_ips(self, rmods_info: List[Dict[str, str]]) -> Dict[str, str]:
        log_debug('Getting RMOD SSH IP addresses')
        rmods_expected_serial_numbers = [rmod_info.get('serial_number') for rmod_info in rmods_info]
        rmods_ssh_ips = {}
        self._connect_via_ssh()

        try:
            for _ in range(5):
                rmods_ssh_ips.clear()
                self._collect_rmods_ssh_ips_from_kea_leases_files(rmods_ssh_ips, rmods_expected_serial_numbers)

                if self._get_missing_rmod_ssh_serial_numbers(rmods_ssh_ips, rmods_expected_serial_numbers):
                    log_debug(f'Getting RMOD IP addresses from {self._name} SSH output failed, retrying')
                    sleep(5)
                else:
                    break
        finally:
            self._disconnect_via_ssh()

        if missing_rmod_ssh_serial_numbers := self._get_missing_rmod_ssh_serial_numbers(rmods_ssh_ips, rmods_expected_serial_numbers):
            raise ResultError(f'Cannot determine RMOD IP addresses because following RMOD serial numbers are absent from {self._name} SSH output: '
                              f'{missing_rmod_ssh_serial_numbers}')

        log_debug(f'RMOD SSH IP addresses: {rmods_ssh_ips}')
        return rmods_ssh_ips

    def _collect_rmods_ssh_ips_from_kea_leases_files(self, rmods_ssh_ips: Dict[str, str], rmods_expected_serial_numbers: List[str]):
        kea_leases_file_path = self._get_kea_leases_file_path()
        kea_leases_file_index = 1
        ssh_response = self._read_kea_leases_file_content(kea_leases_file_path, kea_leases_file_index)

        while 'No such file or directory' not in ssh_response:
            self._update_rmods_ssh_ips_using_ssh_response(rmods_ssh_ips, ssh_response)

            if self._get_missing_rmod_ssh_serial_numbers(rmods_ssh_ips, rmods_expected_serial_numbers):
                log_debug(f'Not all RMOD serial numbers found in {self._name} SSH output, checking next kea leases file')
                kea_leases_file_index += 1
                ssh_response = self._read_kea_leases_file_content(kea_leases_file_path, kea_leases_file_index)
            else:
                break

    def _get_kea_leases_file_path(self) -> str:
        try:
            namespace = '' if self._sw.version.stream >= self._sw.STREAM_26R1 else '-cran1'
            ssh_response = self._execute_via_ssh(f'kubectl exec -n cran1 po{namespace}-oamfh-0 -c ctr{namespace}-dhcp -- cat /tmp/kea-dhcp4.conf')
            ssh_response = loads(ssh_response)
            return ssh_response['Dhcp4']['lease-database']['name']
        except Exception:
            return '/var/lib/kea/kea-leases4.csv' if self._sw.version.stream >= self._sw.STREAM_26R1 else '/var/log/kea-leasesdb/kea-leases4.csv'

    def _read_kea_leases_file_content(self, file_path: str, file_index: int) -> str:
        ssh_cmd = self._create_ssh_cmd_for_reading_kea_leases_file_content(file_path, file_index)
        return self._execute_via_ssh(ssh_cmd)

    def _create_ssh_cmd_for_reading_kea_leases_file_content(self, file_path: str, file_index: int) -> str:
        file_postfix = f'.{file_index}' if file_index > 1 else ''
        namespace = '' if self._sw.version.stream >= self._sw.STREAM_26R1 else '-cran1'
        return f'kubectl exec -n cran1 po{namespace}-oamfh-0 -c ctr{namespace}-dhcp -- cat {file_path}{file_postfix}'

    @staticmethod
    def _update_rmods_ssh_ips_using_ssh_response(rmods_ssh_ips: Dict[str, str], ssh_response: str):
        for line in ssh_response.split('\n'):
            if line and not line.startswith('address'):
                line_parts = line.split(',')
                rmod_ssh_ip = line_parts[0]
                rmod_ssh_serial_number_hex = line_parts[2][-32:].replace(':', '')
                rmod_ssh_serial_number = bytearray.fromhex(rmod_ssh_serial_number_hex).decode()
                rmods_ssh_ips[rmod_ssh_serial_number] = rmod_ssh_ip

    @staticmethod
    def _get_missing_rmod_ssh_serial_numbers(rmods_ssh_ips: Dict[str, str], rmods_expected_serial_numbers: List[str]) -> List[str]:
        return list(set(rmods_expected_serial_numbers) - set(rmods_ssh_ips.keys()))

    def _get_pods_names(self) -> List[str]:
        pods_names = []
        self._connect_via_ssh()

        try:
            ssh_response = self._execute_via_ssh(cmd='kubectl -n cran1 get pod')
        finally:
            self._disconnect_via_ssh()

        for line in ssh_response.split('\n'):
            if line and not line.startswith('NAME'):
                line_parts = line.split()
                pod_name = line_parts[0].strip()
                pod_name = self._remove_instance_id_from_pod_name(pod_name)
                pods_names.append(pod_name)

        return pods_names

    def _check_if_pods_are_running(self, timeout: int, silent: bool = False):
        timeout_msg = f" before {timeout}s timeout" if timeout else ""
        log_info(f'Checking if all PODs from {self._name} are running{timeout_msg}', to_console=not silent)
        expected_pods_statuses = {pod: 'Running' for pod in self._pods}
        self._connect_via_ssh()

        try:
            pods_are_running = wait_for(expected_value=expected_pods_statuses,
                                        abort_if=None,
                                        timeout=timeout,
                                        callback=self._get_current_pods_statuses,
                                        raise_exc=False,
                                        pods_names=self._pods)
        finally:
            self._disconnect_via_ssh()

        if not pods_are_running:
            raise UnexpectedState(f'Not all PODs from {self._name} are running')

    def _check_if_pods_are_restarting(self, timeout: int):
        timeout_msg = f" before {timeout}s timeout" if timeout else ""
        log_info(f'Checking if all PODs from {self._name} are restarting{timeout_msg}', to_console=True)
        self._connect_via_ssh()

        try:
            pods_are_restarting = wait_for(expected_value=True,
                                           abort_if=None,
                                           timeout=timeout,
                                           callback=self._are_pods_restarting,
                                           raise_exc=False)
        finally:
            self._disconnect_via_ssh()

        if not pods_are_restarting:
            raise UnexpectedState(f'Not all PODs from {self._name} are restarting')

    def _are_pods_restarting(self):
        current_pods_statuses = self._get_current_pods_statuses()
        return all([pod_status == 'Terminating' for pod_name, pod_status in current_pods_statuses.items()
                    if 'healing-controller' not in pod_name and 'logservice' not in pod_name])

    def _get_current_pods_statuses(self, pods_names: List[str] = None, without_instance_id: bool = True) -> Dict[str, str]:
        pods_statuses = {}
        ssh_response = self._execute_via_ssh(cmd='kubectl -n cran1 get pod')

        for line in ssh_response.split('\n'):
            if line and not line.startswith('NAME'):
                line_parts = line.split()
                pod_name = line_parts[0].strip()
                if without_instance_id:
                    pod_name = self._remove_instance_id_from_pod_name(pod_name)
                if pods_names is None or pod_name in pods_names:
                    pod_status = line_parts[2].strip()
                    pods_statuses[pod_name] = pod_status

        return pods_statuses

    def _remove_instance_id_from_pod_name(self, pod_name: str) -> str:
        name_parts_count = 3 if self._sw.version.stream >= self._sw.STREAM_26R1 else 4
        return '-'.join(pod_name.split('-')[:name_parts_count])
